mapper.delete:
DELETE FROM tb_part_info t
WHERE t.id IN

    #{id}

mapper.select:
SELECT 
FROM tb_part_info t
WHERE t.row_valid = 1

    AND t.id = #{id}


    AND t.part_code = #{partCode}


    AND t.sn = #{sn}


    AND t.vehicle_node_code = #{vehicleNodeCode}


    AND t.instance_state = #{instanceState}


    AND t.description = #{description}


    AND t.create_time = #{createTime}


    AND t.create_by = #{createBy}


    AND t.modify_time = #{modifyTime}


    AND t.modify_by = #{modifyBy}


    AND t.row_version = #{rowVersion}

ORDER BY t.id DESC

SELECT t.id, t.part_code, t.sn, t.vehicle_node_code, t.config_word, t.supplier_code, t.batch_num,
       t.hardware_ver, t.software_ver, t.hardware_pn, t.software_pn, t.extra, t.instance_state,
       t.source, t.part_type, t.device_category, t.inbound_batch_no, t.source_event_id, t.last_inbound_time,
       t.first_seen_time, t.description, t.create_time, t.create_by, t.modify_time, t.modify_by,
       t.row_version, t.row_valid, p.name AS part_name
FROM tb_part_info t
LEFT JOIN tb_mdm_part p ON t.part_code = p.code AND p.row_valid = 1
WHERE t.row_valid = 1


    AND t.part_code LIKE #{partCode}


    AND t.sn = #{sn}


    AND t.vehicle_node_code = #{vehicleNodeCode}


    AND t.instance_state = #{instanceState}


    AND t.device_category = #{deviceCategory}

ORDER BY t.id DESC

SELECT FROM tb_part_info t WHERE t.row_valid = 1 AND t.part_code = #{partCode}
AND t.sn = #{sn}
AND t.sn IS NULL
ORDER BY t.id DESC LIMIT 1
